<!--
 * @Description: leaflet地图基础操作组件 页面
 * @Author: mhf
 * @Date: 2024/8/19 13:24
 * @Notice: 默认基础配置统一以normal开头
 * @Notice: 自定义变量统一叫customObj
 * @Notice: 私有变量统一叫layerType（当前绘制图层的类型）
-->
<template>
  <div class="leafletMapComp">
    <div id="map" />

    <div class="leafletMapComp-toolbox" v-if="showToolBox">
      <toolbox ref="toolbox" :map="map"></toolbox>
    </div>
  </div>
</template>

<script>
import defaultCoordinates from "@/utils/defaultCoordinates";
import HeatmapOverlay from "@/utils/leafletMap/heatmap/leaflet-heatmap.js";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import "@/utils/leafletMap/markerCluster/MarkerCluster.css";
import "@/utils/leafletMap/markerCluster/MarkerCluster.Default.css";

require("@/utils/leafletMap/leaflet.ChineseTmsProviders.js");
require("@/utils/leafletMap/tileLayer.baidu.js");
require("@/utils/leafletMap/leaflet.mapCorrection.min.js");
require("@/utils/leafletMap/heatmap/heatmap.js");
require("@/utils/leafletMap/markerCluster/featuregroup.subgroup.js");
require("@/utils/leafletMap/markerCluster/leaflet.markercluster-src.js");

import toolbox from "@/components/leafletMapComp/toolbox.vue";

export default {
  name: "leafletMapComp",
  components: { toolbox },
  mixins: [],
  props: {
    showToolBox: {
      type: Boolean,
      default: true,
    }, // 是否展示工具箱

    showControl: {
      type: Boolean,
      default: true,
    }, // 是否展示zoomControl控件

    zoomControlConfig: {
      type: Object,
      default() {
        return {
          position: "bottomright",
        };
      },
    }, // 仅当showControl为true时生效

    mapConfig: {
      type: Object,
      default() {
        return {
          zoom: 10,
          maxZoom: 19,
          attributionControl: false,
          zoomControl: false,
        };
      },
    }, // 地图配置项

    tileLayerConfig: {
      type: Object,
      default() {
        return {
          layer: "vec", // custom_online
        };
      },
    }, //  地图瓦片图层配置项
  },
  computed: {},
  watch: {},
  filters: {},
  data() {
    return {
      map: null,
      mapCenter: {
        lng: defaultCoordinates.longitude,
        lat: defaultCoordinates.latitude,
      },
      mcgLayer: undefined, // 点聚合图层
      chooseMarker: undefined, // 当前选中的点位
    };
  },
  methods: {
    initMap() {
      this.map = L.map("map", {
        center: [this.mapCenter.lat, this.mapCenter.lng],
        crs: L.CRS.Baidu,
        ...this.mapConfig,
      });

      if (this.showControl) {
        L.control.zoom(this.zoomControlConfig).addTo(this.map);
      }

      L.tileLayer.baidu(this.tileLayerConfig).addTo(this.map);
      this.listenClick();
      // 向外暴露map实例对象
      this.$emit("getMapInstance", this.map);
    },
    /******** ↓ 热力图 ↓  ********/
    /**
     * 添加热力图
     * @param: data, config, customObj
     * @author: mhf
     * @time: 2024-08-19 15:48:28
     **/
    addHeatmapLayer(heatConfig) {
      let normalConfig = {
        // 数据点的半径，重要提示：如果caleRadius为false，则以像素为单位测量半径。
        // 如果caleRadius为true，则以地图的比例测量。
        radius: 0.1,
        maxOpacity: 0.7,
        // 是否应根据缩放级别相应地缩放半径
        scaleRadius: true,
        // 如果设置为false，热图将使用全局最大值进行着色
        // 如果激活:使用当前地图边界内的最大数据
        // 当useLocalExtremas为true时，总会有一个红点
        // 这定义了热图是否应通过setData/addData使用全局极值集或局部极值（当前显示视口的最大值和最小值）
        useLocalExtrema: true,
        // 数据中的哪个字段名表示纬度-默认的“lat”
        latField: "lat",
        // 数据中的哪个字段名表示经度-默认的“lng”
        lngField: "lng",
        // 数据中的哪个字段名表示数据值-默认“value”
        valueField: "count",
      };
      let normalObj = {
        layerType: "draw-heatmap-layer", // 组件内置字段，请勿重复使用
      };
      let { data, config = normalConfig, customObj } = heatConfig;
      var heatmapLayer = new HeatmapOverlay(config);
      heatmapLayer.customObj = Object.assign(normalObj, customObj) || normalObj;
      this.map.addLayer(heatmapLayer);
      heatmapLayer.setData(data); // API: addData, setData
      console.warn(heatmapLayer, "添加热力图");
    },
    /******** ↑ 热力图 ↑  ********/

    /******** ↓ 点聚合 ↓  ********/
    /**
     * 点聚合（同一个坐标多个点位也可做区分）
     * @param: markerArr, bindType: 绑定类型[tooltip(默认), popup]
     * markerArr示例： [
     {
          latlng: [37.11043744529622, 114.87851313180274], // 或者 {lat: 37.21, lng: 114.81}
          myIcon: {
            iconUrl: "/img/btnIcon/normalPoint.png",
            iconSize: [32, 32],
            iconAnchor: [16, 16],
          },
          myChooseIcon: {
            iconUrl: "/img/btnIcon/choosePoint.png",
            iconSize: [32, 32],
            iconAnchor: [16, 16],
          },
          customObj: {
            id: 0
          }
        },
     ]
     *
     * @return:
     * @author: mhf
     * @time: 2024-08-21 11:22:07
     **/
    addMarkerCluster(markerClusterConfig) {
      console.warn(markerClusterConfig, "绘制点聚合组");
      let {
        markerArr = [], // 点位数组
        key = "", // 绑定字段 (需在customObj内部)
        bindType = "tooltip", // 绑定类型 [tooltip, popup]
        tooltipConfig = {}, // tooltip 配置
        resetMarker = true, // 是否重置 marker
      } = markerClusterConfig;
      this.mcgLayer = L.markerClusterGroup();
      let group = L.featureGroup.subGroup(this.mcgLayer);
      const normalTooltipConfig = {
        // 永久打开
        permanent: true,
        // 打开 Tooltip 的方向。可能的值有：right、left、 top、bottom、center、auto。 auto 将之间进行动态切换 right 和 left 根据地图上的工具提示位置。
        direction: "top",
        // Tooltip 位置的可选偏移。
        offset: [0, -20],
      };
      const normalIcon = {
        iconUrl: "/img/mapIcon/redPoint.png",
        iconSize: [32, 32],
        iconAnchor: [16, 16],
      };
      this.mcgLayer.addTo(this.map);

      for (let i = 0; i < markerArr.length; i++) {
        let title = JSON.stringify(markerArr[i]?.customObj[key]);
        let marker = L.marker(markerArr[i].latlng, {
          icon: L.icon(markerArr[i].myIcon || normalIcon),
          customObj: {
            ...markerArr[i].customObj,
            layerType: "draw-marker-cluster-layer",
          },
        });
        if (key && title) {
          if (bindType === "tooltip") {
            marker.bindTooltip(title, tooltipConfig || normalTooltipConfig);
          } else if (bindType === "popup") {
            marker.bindPopup(title).openPopup();
          }
        }

        marker.on("click", (e) => {
          this.$emit("markerClick", e);
          // 如果 resetMarker 为 true，则重置当前选中的点位的图标
          if (resetMarker) {
            this.drawChooseMarker({
              latlng: e.latlng,
              myChooseIcon: markerArr[i].myChooseIcon,
              customObj: { ...markerArr[i].customObj },
            });
          }
          console.warn("点位点击了", e.target.options);
        });
        marker.addTo(group);
      }

      group.addTo(this.map);
    },
    /******** ↑ 点聚合 ↑  ********/

    /******** ↓ 绘制点相关 ↓  ********/
    /**
     * 单独的绘制chooseMarker
     * @param: latlng,// [] or {}; customObj // {}
     * @return:
     * @author: mhf
     * @time: 2024-08-21 18:40:14
     **/
    drawChooseMarker(markerConfig) {
      console.warn(markerConfig, "绘制选中的点位");
      let { latlng, myChooseIcon, customObj } = markerConfig;

      const normalChooseIcon = {
        iconUrl: "/img/mapIcon/blackPoint.png",
        iconSize: [32, 32],
        iconAnchor: [16, 16],
      };

      // 如果 chooseMarker 存在的话就先移除该图标
      if (this.chooseMarker) {
        this.map.removeLayer(this.chooseMarker);
      }

      this.chooseMarker = new L.Marker(latlng, {
        icon: L.icon({
          ...(myChooseIcon || normalChooseIcon),
          className: "drawChooseMarker",
        }),
        customObj: {
          ...customObj,
          layerType: "draw-choose-marker-layer",
        },
      });
      this.map.addLayer(this.chooseMarker);
      this.chooseMarker.on("click", (e) => {
        this.$emit("markerClick", e);
      });
    },

    /**
     * 绘制点位组
     * @param: markerArr, key, bindType: 绑定类型[tooltip(默认), popup], tooltipConfig, resetMarker
     * markerArr示例： [
     *      {
     *           latlng: [37.11043744529622, 114.87851313180274], // 或者 {lat: 37.21, lng: 114.81}
     *           myIcon: {
     *             iconUrl: "/img/btnIcon/normalPoint.png",
     *             iconSize: [32, 32],
     *             iconAnchor: [16, 16],
     *           },
     *           myChooseIcon: {
     *             iconUrl: "/img/btnIcon/choosePoint.png",
     *             iconSize: [32, 32],
     *             iconAnchor: [16, 16],
     *           },
     *           customObj: {
     *             id: 0
     *           }
     *         },
     *      ]
     * @return:
     * @author: mhf
     * @time: 2024-08-26 15:03:52
     **/
    addMarkerGroup(markerGroupConfig) {
      console.warn(markerGroupConfig, "绘制点位组");
      let {
        markerArr = [], // 点位数组
        key = "", // 绑定字段 (需在customObj内部)
        bindType = "tooltip", // 绑定类型 [tooltip, popup]
        tooltipConfig = {}, // tooltip 配置
        resetMarker = true, // 是否重置 marker
        groupType = undefined, // 用来区分是哪一个组
        isDivIcon = false, // 是否是divIcon
        className = "normal-divIcon", // divIcon的类名
        subClassName = "normal-divIcon-sub", // 内置告警动画[默认]
      } = markerGroupConfig;
      let markerGroup = [],
        markerGroupIns;
      const normalTooltipConfig = {
        // 永久打开
        permanent: true,
        // 打开 Tooltip 的方向。可能的值有：right、left、 top、bottom、center、auto。 auto 将之间进行动态切换 right 和 left 根据地图上的工具提示位置。
        direction: "top",
        // Tooltip 位置的可选偏移。
        offset: [0, -20],
      };
      const normalIcon = {
        iconUrl: "/img/mapIcon/redPoint.png",
        iconSize: [32, 32],
        iconAnchor: [16, 16],
      };

      /* 默认使用基础图标，如设置了isDivIcon则可以个性化图标样式 */
      function getIcon(myIcon) {
        if (isDivIcon) {
          return L.divIcon({
            className,
            html: `<div style="position: relative;">
          <div style="width: ${
            myIcon.iconSize[0] || normalIcon.iconSize[0]
          }px; height: ${myIcon.iconSize[1] || normalIcon.iconSize[1]}px;">
            <img style="width: 100%;" src="${
              myIcon.iconUrl || normalIcon.iconUrl
            }" />
          </div>
          <div class="${subClassName}"></div>
        </div>`,
            iconSize: [
              myIcon.iconSize[0] || normalIcon.iconSize[0],
              myIcon.iconSize[1] || normalIcon.iconSize[1],
            ], // marker宽高
            iconAnchor: myIcon.iconAnchor || normalIcon.iconAnchor, // 文字标注相对位置
          });
        } else {
          return L.icon(myIcon || normalIcon);
        }
      }

      for (let i = 0; i < markerArr.length; i++) {
        let title = JSON.stringify(markerArr[i]?.customObj[key]);
        let marker = new L.marker(markerArr[i].latlng, {
          icon: getIcon(markerArr[i].myIcon),
          customObj: {
            ...markerArr[i].customObj,
            layerType: "draw-marker-group-layer",
          },
        });
        if (key && title) {
          if (bindType === "tooltip") {
            marker.bindTooltip(title, tooltipConfig || normalTooltipConfig);
          } else if (bindType === "popup") {
            marker.bindPopup(title).openPopup();
          }
        }

        markerGroup.push(marker);
        markerGroupIns = L.featureGroup(markerGroup);

        marker.on("click", (e) => {
          this.$emit("markerClick", e);
          // 如果 resetMarker 为 true，则重置当前选中的点位的图标
          if (resetMarker) {
            this.drawChooseMarker({
              latlng: e.latlng,
              myChooseIcon: markerArr[i].myChooseIcon,
              customObj: { ...markerArr[i].customObj },
            });
          }
          console.warn("点位点击了", e.target.options);
        });
      }

      this.map.addLayer(markerGroupIns);

      /* 抛出组的实例对象 */
      this.$emit("markerGroupIns", { groupType, markerGroupIns });
    },

    /******** ↑ 绘制点相关 ↑  ********/

    /******** ↓ fixMe??? 绘制线相关 ↓  ********/

    /******** ↑ fixMe??? 绘制线相关 ↑  ********/

    /******** ↓ 绘制面相关 ↓  ********/
    /**
     * 绘制给定的GeoJson数据[区县/区域边界]
     * todo: 目前文字暂不支持自定义样式
     * @param: style, highlightStyle, features, isHighlight, isFeatureFont
     * @return:
     * @author: mhf
     * @time: 2024-08-22 09:53:23
     **/
    addBoundary(boundaryConfig) {
      let {
        style = {}, // feature样式
        highlightStyle = {}, // feature高亮样式
        features = require("./xingtai.min").default, // 边界数据[geojson]
        isHighlight = true, // 是否需要鼠标移入高亮
        isFeatureFont = true, // 是否需要feature文字
      } = boundaryConfig;
      // 定义默认样式
      const normalStyle = {
        color: "#1492ff", // 边框颜色
        weight: 3, // 边框粗细
        opacity: 0.4, // 透明度
        fillColor: "#fff000", // 区域填充颜色
        fillOpacity: 0.5, // 区域填充颜色的透明
        dashArray: "5", // 冲点线样式
        className: "addBoundary",
      };

      // 定义悬停样式
      const normalHighlightStyle = {
        weight: 5, // 增加边框粗细
        color: "#666", // 改变边框颜色
        dashArray: "", // 取消冲点线样式
        fillOpacity: 0.7, // 改变填充透明度
      };

      // 创建一个方法来生成带有文字的 marker
      const createLabelMarker = (latlng, text, map) => {
        const divIcon = L.divIcon({
          className: "label-marker",
          html: `<div>${text}</div>`, // 保留原有 HTML 内容
          iconSize: [50, 20], // 根据实际需要调整尺寸
          iconAnchor: [40, 10], // 根据实际需要调整位置
        });
        const marker = L.marker(latlng, { icon: divIcon });
        marker.addTo(map);
        return marker;
      };

      const highlightFeature = (e) => {
        this.$emit("geojsonLayerEvent", {
          data: e,
          eventType: "mouseover",
        });
        if (isHighlight) {
          // 如果需要设置高亮
          const layer = e.target;
          layer.setStyle(highlightStyle || normalHighlightStyle);

          // 如果地图上存在高亮层，则重置其样式
          if (layer._map) {
            layer.bringToFront();
          }

          // 改变文字颜色
          const labelMarker = layer.options.labelMarker;
          if (labelMarker) {
            labelMarker.setIcon(
              L.divIcon({
                html: `<div>${layer.feature.properties.name}</div>`, // 保留原有 HTML 内容
                iconSize: [70, 20], // 根据实际需要调整尺寸
                iconAnchor: [40, 10], // 根据实际需要调整位置
                className: "label-marker label-marker-highlight", // 添加高亮样式
              })
            );
          }
        }
      };

      const resetHighlight = (e) => {
        this.$emit("geojsonLayerEvent", {
          data: e,
          eventType: "mouseout",
        });

        if (isHighlight) {
          const layer = e.target;
          layer.setStyle(style || normalStyle);

          // 恢复文字颜色
          const labelMarker = layer.options.labelMarker;
          if (labelMarker) {
            labelMarker.setIcon(
              L.divIcon({
                html: `<div>${layer.feature.properties.name}</div>`, // 保留原有 HTML 内容
                iconSize: [50, 20], // 根据实际需要调整尺寸
                iconAnchor: [40, 10], // 根据实际需要调整位置
                className: "label-marker", // 恢复原始样式
              })
            );
          }
        }
      };

      const onClick = (e) => {
        this.$emit("geojsonLayerEvent", {
          data: e,
          eventType: "click",
        });
        console.warn(e.target.feature, "点击了GeoJson图层"); // 这里可以替换为你想要的操作
      };

      // 添加 geoJSON 图层并设置样式
      const geojsonLayer = L.geoJSON(features, {
        style: style || normalStyle,
        onEachFeature: (feature, layer) => {
          // 绑定事件
          layer.on({
            mouseover: highlightFeature,
            mouseout: resetHighlight,
            click: onClick,
          });

          if (isFeatureFont) {
            // 如果需要设置区县文字

            // 获取区县名称
            const name = feature.properties.name || "未知";

            // 创建带有文字的 marker
            const centerLatLng = layer.getBounds().getCenter();
            layer.options.labelMarker = createLabelMarker(
              centerLatLng,
              name,
              this.map
            );
          }
        },
      }).addTo(this.map);
    },
    /******** ↑ 绘制面相关 ↑  ********/

    /******** ↓ 图层移除操作 ↓  ********/
    /**
     * 移除点聚合图层
     * @param:
     * @return:
     * @author: mhf
     * @time: 2024-08-21 16:04:01
     **/
    removeMarkerCluster() {
      return new Promise((resolve, reject) => {
        try {
          if (this.mcgLayer) {
            this.map.removeLayer(this.mcgLayer);
          }
          resolve();
        } catch (err) {
          reject(err);
        }
      });
    },

    /**
     * 移除指定图层[热力图]
     * @param: customObj , removeType 二选一即可
     * @return:
     * @author: mhf
     * @time: 2024-08-19 16:00:28
     **/
    removeLayerByCustomObj(removeConfig) {
      const { customObj, removeType } = removeConfig;
      return new Promise((resolve, reject) => {
        try {
          for (const layerId in this.map._layers) {
            const layer = this.map._layers[layerId];
            if (!layer || !layer.customObj) continue;
            const { layerType, ...obj } = layer.customObj;
            if (
              (removeType && layerType === removeType) ||
              JSON.stringify(obj) === JSON.stringify(customObj)
            ) {
              console.warn("移除符合条件的图层");
              this.map.removeLayer(layer);
              break;
            }
          }

          resolve();
        } catch (err) {
          reject(err);
        }
      });
    },

    /**
     * 移除组
     * @param: 组的实例
     * @howToUse: 必须配合markerGroupIns使用，在父组件中接收组的实例，并通过groupType做区分
     * @return:
     * @author: mhf
     * @time: 2024-08-19 16:00:28
     **/
    removeLayerGroup(groupIns) {
      this.map.removeLayer(groupIns);
    },

    /******** ↑ 图层移除操作 ↑  ********/

    /******** ↓ 其他基础操作 ↓  ********/
    /**
     * 移动地图到指定位置
     * @param:
     * @return:
     * @author: mhf
     * @time: 2024-08-21 17:51:19
     **/
    mapFlyTo(flyConfig) {
      let nowZoom = this.map.getZoom();
      let { lat, lng, zoom } = flyConfig;
      this.map.flyTo([lat, lng], zoom || nowZoom);
    },

    listenClick() {
      this.map.on("click", (e) => {
        console.warn(e, "点击了地图");
        /* 移除选中的点位图层 */
        if (this.chooseMarker) {
          this.map.removeLayer(this.chooseMarker);
        }
      });
    },
    /******** ↑ 其他基础操作 ↑  ********/
  },
  created() {},
  mounted() {
    this.initMap();
  },
  destroyed() {},
};
</script>

<style lang="scss" scoped>
