<template>
  <div class="toolbox">
    <div
      v-for="(item, index) in iconList"
      :key="item.id"
      @click="changeIcon(item, index)"
    >
      <div class="toolbox-item">
        <el-tooltip
          v-if="showTooltip"
          effect="light"
          placement="top"
          :content="item.name"
          :visible-arrow="false"
        >
          <div v-if="!item.children">
            <i
              :style="index === selectIcon ? 'color:#1492ff' : ''"
              :class="item.icon"
            />
          </div>
          <el-dropdown v-else @command="polygonClick">
            <div class="toolbox-item-drop">
              <i :class="item.icon" /> {{ item.name
              }}<i class="el-icon-arrow-down" style="font-weight: bold" />
            </div>
            <el-dropdown-menu slot="dropdown">
              <el-dropdown-item
                v-for="(item1, i) in item.children"
                :key="i"
                :command="item1.name"
              >
                <i :class="item1.icon" /> <span>{{ item1.name }}</span>
              </el-dropdown-item>
            </el-dropdown-menu>
          </el-dropdown>
        </el-tooltip>
      </div>
    </div>
  </div>
</template>

<script>
import * as turf from "@turf/turf";

export default {
  name: "toolbox",
  components: {},
  mixins: [],
  props: {
    map: {
      type: Object,
      default() {
        return {};
      },
    },
  },
  computed: {},
  watch: {},
  filters: {},
  data() {
    return {
      showTooltip: true, // 是否显示tooltip,解决tooltip异常一直显示的问题
      iconList: [
        {
          id: 1,
          name: "工具箱",
          icon: "iconfont if-gongjuxiang",
          children: [
            {
              id: 11,
              name: "测距",
              icon: "iconfont if-ceju",
            },
            {
              id: 22,
              name: "经纬度",
              icon: "iconfont if-jingweidu",
            },
            {
              id: 33,
              name: "清空",
              icon: "iconfont if-biaodancaozuo-shanchu",
            },
          ],
        },
      ],
      selectIcon: "",
      maxLength: 0, // 总距离
      line: "", // 绘制的折线
      tips: "", //  距离提示
      isdrawLine: false, // 是否画线
      lineList: [], // 线的点集合
      prevPoint: "", // 上个点坐标
      moveing: "", // 移动中的线
      shapeOptions: {
        // 线的样式
        color: "#F54124",
        weight: 4,
        opacity: 0.8,
        fill: false,
        clickable: true,
      },
      allLineList: [], // 所有画线集合，用于清除
      allLineMarker: [], // 所有画线展示距离点集合
      allLineMarkerGruop: [],
      allMaxLength: [], // 所有画线距离集合
      lineMaker: "", // 画线的marker
      popupLayer: null,
    };
  },
  methods: {
    polygonClick(name) {
      console.log(name, "name");
      if (name === "测距") {
        this.ranging();
      } else if (name === "经纬度") {
        this.getLatLng();
      } else if (name === "清空") {
        /* 取消绑定 */
        this.map.getContainer().style.cursor = "";
        // this.map.off("click");
        // this.map.off("mousemove");
        // this.map.off("contextmenu");
        var that = this;
        this.showTooltip = false;
        this.$nextTick(() => {
          that.showTooltip = true;
          this.$confirm("是否确认删除绘制痕迹?").then(function () {
            that.clearLine();
            that.popupLayer.remove();
            that.selectIcon = "";
          });
        });
      }
    },

    changeIcon(item, index) {
      this.selectIcon = index;
    },

    // 点击测距工具
    ranging() {
      if (!this.isdrawLine) {
        this.map.off("click");
        this.map.off("mousemove");
        this.map.off("contextmenu");
        this.map.getContainer().style.cursor = "crosshair";
        // 绘制的折线
        this.line = new L.Polyline([], this.shapeOptions);
        // 地图上添加折线
        this.map.addLayer(this.line);
        // 实例化量距提示
        this.tips = new L.Tooltip(this.map);
        // 设置地图的鼠标按下事件
        this.map.on("click", this.drawLine);
        this.isdrawLine = true; // 是否正在绘制
        // 设置地图的右击事件
        this.map.on("contextmenu", this.stopLine);
      } else {
        this.selectIcon = "";
        this.map.getContainer().style.cursor = "";
        this.lineList = [];
        this.maxLength = 0;
        this.prevPoint = "";
        this.isdrawLine = false;
        // 移除事件
        this.map.off("click");
        this.map.off("mousemove");
        this.map.off("contextmenu");
      }
    },

    // 开始画线的点击事件
    drawLine(e) {
      this.lineList.push(e.latlng); // 绘制的折线的节点集
      // 绘制的折线添加进集合
      this.line.addLatLng(e.latlng);
      // 地图添加鼠标移动事件
      this.map.on("mousemove", this.moveLine);
    },

    // 移动线
    moveLine(e) {
      if (this.isdrawLine) {
        // 是否正在绘制
        this.setNodeMarkers();
        // 将上次的移除
        if (this.moveing) {
          // 绘制过程中的折线
          this.map.removeLayer(this.moveing);
        }
        // 获取上个点坐标
        this.prevPoint = this.lineList[this.lineList.length - 1];
        // 绘制最后一次的折线
        this.moveing = new L.Polyline(
          [this.prevPoint, e.latlng],
          this.shapeOptions
        );
        // 添加到地图
        this.map.addLayer(this.moveing);
      }
    },

    // 右击暂停画线
    stopLine(e) {
      this.selectIcon = "";
      this.map.getContainer().style.cursor = "";
      /* 显示两点距离*/
      var lineArr = [];
      this.lineList.map((item) => lineArr.push([item.lng, item.lat]));
      var line = turf.lineString(lineArr);
      // 结果为 19.653444490831294，单位为千米，单位还可以设置为degrees, radians, miles, or kilometers
      this.maxLength =
        turf.length(line, { units: "kilometers" }).toFixed(2) + "公里";
      this.setLineMarker(this.maxLength);
      if (this.isdrawLine) {
        // 清除上次的
        if (this.moveing) {
          this.map.removeLayer(this.moveing);
          this.moveing = null;
        }
        this.allLineList.push(this.line);
        this.allLineMarker.push(this.lineMaker);
        this.allMaxLength.push(this.maxLength);
        this.lineList = [];
        this.maxLength = 0;
        this.prevPoint = "";
        this.isdrawLine = false;
        // 移除事件
        this.map.off("click");
        this.map.off("mousemove");
        this.map.off("contextmenu");
      }
    },

    clearLine() {
      this.isdrawLine = false;
      this.allLineList.map((item) => this.map.removeLayer(item));
      this.allLineList = [];
      this.allLineMarker.map((item) => this.map.removeLayer(item));
      this.allLineMarkerGruop.map((item) => {
        item.map((item1) => this.map.removeLayer(item1));
      });
      this.allLineMarker = [];
      this.allMaxLength = [];
      this.allLineMarkerGruop = [];
    },

    // 设置节点功能
    setNodeMarkers() {
      var markerGroup = [];
      var markerIcon = "";
      markerIcon = L.divIcon({
        className: "nodeIcon",
        // html:
        //   '<div class="mapIcon">' +
        //   '<img width="12" height="12px" src="/img/mapIcon/point.png" />' +
        //   '</div>',
        iconSize: [12, 12], // marker宽高
      });
      this.lineList.map((item) => {
        var nodeMarker = new L.Marker(item, { icon: markerIcon });
        markerGroup.push(nodeMarker);
      });
      this.map.addLayer(L.layerGroup(markerGroup));
      this.allLineMarkerGruop.push(markerGroup);
      // 监听点击节点操作
      this.handleNodeClick(markerGroup);
    },

    // 监听点击节点操作
    handleNodeClick(markerGroup) {
      var that = this;
      console.log(markerGroup, "markerGroup");
      markerGroup.map((marker, i) =>
        marker.on("click", function (e) {
          console.log(e, "e");
          that.allLineList.map((item, index) => {
            item._latlngs.map((item1, index1) => {
              if (item1 === e.latlng) {
                item._latlngs.splice(index1, 1);
                // 删除后超过两个节点
                if (item._latlngs.length > 1) {
                  // 删除对应线
                  that.map.removeLayer(that.allLineList[index]);
                  // 删除对应节点marker
                  that.allLineMarkerGruop[index].map((newNode) =>
                    that.map.removeLayer(newNode)
                  );
                  // 删除对应节点组对应marker
                  that.allLineMarkerGruop[index].splice(index1, 1);
                  // 删除对应距离marker
                  that.map.removeLayer(that.allLineMarker[index]);
                  // 计算新的距离
                  var lineArr = [];
                  that.allLineList[index]._latlngs.map((item) =>
                    lineArr.push([item.lng, item.lat])
                  );
                  var line = turf.lineString(lineArr);
                  that.allMaxLength[index] =
                    turf.length(line, { units: "kilometers" }).toFixed(2) +
                    "公里";
                  // 更新对应的线的距离marker为新的marker
                  var markerIcon;
                  markerIcon = L.divIcon({
                    className: "markerBox",
                    html:
                      '<div class="mapIcon">' +
                      '<img width="32px" height="32px" src="/img/btnIcon/marker.png" /><span class="markerTips">' +
                      that.allMaxLength[index] +
                      "</span></div>", // marker标注
                    iconSize: [32, 32], // marker宽高
                  });
                  that.allLineMarker[index] = new L.Marker(
                    that.allLineList[index]._latlngs[
                      that.allLineList[index]._latlngs.length - 1
                    ],
                    { icon: markerIcon }
                  );
                  // 更新新的距离marker
                  that.map.addLayer(that.allLineMarker[index]);
                  // 更新删除节点后新的线
                  that.map.addLayer(that.allLineList[index]);
                  // 更新删除节点marker后的marker(生成的节点maker必须比距离marker晚，不然会被覆盖)
                  that.allLineMarkerGruop[index].map((newNode) =>
                    that.map.addLayer(newNode)
                  );
                } else {
                  // 少于两条直接删除线和所有数据
                  // 删除对应线
                  that.map.removeLayer(that.allLineList[index]);
                  // 删除所有对应节点marker
                  that.allLineMarkerGruop[index].map((newNode) =>
                    that.map.removeLayer(newNode)
                  );
                  // 删除对应距离marker
                  that.map.removeLayer(that.allLineMarker[index]);
                  // 删除总线数组对应线
                  that.allLineList.splice(index, 1);
                  // 删除距离数组对应距离
                  that.allMaxLength.splice(index, 1);
                  // 删除总线距离marker 对应marker
                  that.allLineMarker.splice(index, 1);
                  // 删除总节点组对应组
                  that.allLineMarkerGruop.splice(index, 1);
                }
              }
            });
          });
        })
      );
    },

    // 设置线标点展示名字
    setLineMarker(distance) {
      var markerIcon;
      markerIcon = L.divIcon({
        className: "markerBox",
        html:
          '<div class="mapIcon"><img width="32px" height="32px" src="/img/btnIcon/marker.png" /><span class="markerTips">' +
          distance +
          "</span></div>", // marker标注
        iconSize: [32, 32], // marker宽高
      });
      this.lineMaker = new L.Marker(this.lineList[this.lineList.length - 1], {
        icon: markerIcon,
      });
      this.map.addLayer(this.lineMaker);
    },

    // 点击 经纬度工具
    getLatLng() {
      this.map.getContainer().style.cursor = "crosshair";
      this.map.on("click", this.drawLatLng);
    },

    // 经纬度工具的点击事件
    drawLatLng(e) {
      this.selectIcon = "";
      this.map.getContainer().style.cursor = "";
      this.map.off("click");
      this.map.off("mousemove");
      this.map.off("contextmenu");
      this.popupLayer = L.popup()
        .setLatLng(e.latlng)
        .setContent(
          "经度 : " + e.latlng.lng + "<br />" + "纬度 : " + e.latlng.lat
        )
        .openOn(this.map);
    },
  },
  created() {},
  mounted() {},
  destroyed() {},
};
</script>

